<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {useApp} from '../stores/app'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {api,authGeneration,newKey} from '../api'
import {cacheGet,cacheSet,accountId,backendBase} from '../platform/bridge'
import type {RevisionHistory,SelectionDetail,SelectionRevisionAction,SelectionEditResult} from '../api/selection-edits'
const props=defineProps<{bookId:string;branchId:string;readOnly?:boolean}>(),emit=defineEmits<{close:[];busy:[value:boolean];saved:[result:SelectionEditResult]}>(),history=ref<RevisionHistory|null>(null),busy=ref(false),error=ref(''),pages=ref<(number|undefined)[]>([undefined]),mutating=ref(false),ready=ref(false)
interface Intent {bookId:string;branchId:string;key:string;body:SelectionRevisionAction}
const pending=ref<Intent|null>(null),intentKey='selection-revision-intent:'+props.branchId
const store=useApp(),auth=authGeneration(),owner=accountId(),base=backendBase();let disposed=false,epoch=0
const active=()=>!disposed&&auth===authGeneration()&&owner===accountId()&&base===backendBase()
async function load(){const token=++epoch;busy.value=true;error.value='';try{const cursor=pages.value.at(-1),value=await api<RevisionHistory>('/branches/'+props.branchId+'/revision-history?limit=20'+(cursor===undefined?'':'&beforeSequence='+cursor));if(!disposed&&auth===authGeneration()&&token===epoch)history.value=value}catch(e){if(!disposed&&token===epoch)error.value=(e as Error).message}finally{if(!disposed&&token===epoch)busy.value=false}}
function next(){if(history.value?.nextBeforeSequence){pages.value.push(history.value.nextBeforeSequence);void load()}}
function previous(){if(pages.value.length>1){pages.value.pop();void load()}}
async function submit(){const intent=pending.value;if(!active()||!intent)return;const result=await api<SelectionEditResult>('/branches/'+props.branchId+'/selection-revisions',{method:'POST',body:intent.body,key:intent.key});if(!active())return;try{await cacheSet(intentKey,null)}catch{if(active())error.value='修订已保存，本机回执清理可稍后重试'}if(!active())return;pending.value=null;mutating.value=false;emit('busy',false);emit('saved',result)}
async function choose(revisionId:string,restore=false){if(!active()||props.readOnly||!store.online||mutating.value||pending.value||!ready.value)return;mutating.value=true;emit('busy',true);error.value='';try{const detail=await api<SelectionDetail>('/revisions/'+revisionId+'/selection-edit');if(!active())return;if(detail.bookId!==props.bookId||detail.branchId!==props.branchId)throw new Error('候选不属于这条故事线');const body:SelectionRevisionAction={action:restore?'restore_original':'select_candidate',...(restore?{}:{candidateRevisionId:revisionId}),expectedSourceHeadRevisionId:detail.sourceHeadRevisionId,expectedTargetHeadRevisionId:detail.targetHeadRevisionId,sourcePolicy:detail.baseRevisionId===detail.sourceHeadRevisionId?'requireUnchanged':'forkPinned'},intent={bookId:props.bookId,branchId:props.branchId,key:newKey(),body};await cacheSet(intentKey,intent);if(!active())return;pending.value=intent;await submit()}catch(e){if(active())error.value=(e as Error).message}finally{if(active()){mutating.value=false;emit('busy',false)}}}
async function retry(){if(!active()||props.readOnly||!store.online||mutating.value||!pending.value)return;mutating.value=true;emit('busy',true);error.value='';try{await submit()}catch(e){if(active())error.value=(e as Error).message}finally{if(active()){mutating.value=false;emit('busy',false)}}}
onBeforeRouteLeave(()=>!mutating.value);onBeforeRouteUpdate(()=>!mutating.value)
onMounted(async()=>{try{const value=await cacheGet<Intent|null>(intentKey);if(active()&&value){if(value.bookId!==props.bookId||value.branchId!==props.branchId||typeof value.key!=='string'||!value.body||!['select_candidate','restore_original'].includes(value.body.action))throw new Error('上次修订的记录无法校验，请保留当前版本');pending.value=value}if(active())ready.value=true}catch(e){if(active())error.value=(e as Error).message;return}if(active())void load()});onUnmounted(()=>{disposed=true;epoch++})
</script>
<template><div class="server-revision-history"><small v-if="readOnly" class="muted">已归档 · 只读</small><p v-if="error" role="alert" class="error">{{error}}<button @click="load">重试</button></p><div v-if="pending" class="revision-pending"><p>上次修订尚未确认，原版本保留。</p><button :disabled="mutating||readOnly||!store.online" @click="retry">{{mutating?'正在确认…':'确认上次修订'}}</button></div><button v-else-if="history?.items.some(row=>row.kind==='selection_edit')" :disabled="busy||mutating||readOnly||!ready||!store.online" @click="choose(history!.headRevisionId,true)">恢复原选区</button><p v-if="busy" role="status">正在打开版本…</p><ol v-else aria-label="故事版本记录"><li v-for="row in history?.items||[]" :key="row.revisionId"><span class="history-point"/><article><div><strong>{{row.kind==='selection_edit'?'正文修订':'故事版本'}} · v{{row.sequence}}</strong><small v-if="row.revisionId===history?.headRevisionId">当前</small></div><small>{{new Date(row.createdAt).toLocaleString()}}{{row.restored?' · 已恢复原文':''}}</small><RouterLink :to="{path:'/books/'+bookId+'/read',query:{branch:branchId,revision:row.revisionId,chapter:row.startAnchor?.chapterId}}" @click="emit('close')">阅读这个版本</RouterLink><button v-if="row.kind==='selection_edit'&&row.revisionId!==history?.headRevisionId" :disabled="mutating||readOnly||!!pending||!ready||!store.online" @click="choose(row.revisionId)">使用这个版本</button></article></li></ol><div class="actions"><button :disabled="busy||mutating||pages.length===1" @click="previous">上一页</button><span>{{pages.length}}</span><button :disabled="busy||mutating||!history?.nextBeforeSequence" @click="next">下一页</button></div></div></template>
<style scoped>.server-revision-history{display:grid;gap:24px}.server-revision-history ol{list-style:none;margin:0;padding:0}.server-revision-history li{display:grid;grid-template-columns:24px minmax(0,1fr);gap:16px;position:relative;padding-bottom:24px}.server-revision-history li:not(:last-child):before{position:absolute;content:'';left:6px;top:14px;bottom:0;border-left:1px solid var(--border)}.history-point{height:13px;width:13px;border-radius:50%;background:var(--accent);margin-top:6px}.server-revision-history article{display:grid;gap:8px}.server-revision-history article>div{display:flex;gap:12px;align-items:center}.server-revision-history strong{font:20px var(--font-serif,serif)}.server-revision-history small{color:var(--muted);font-size:12px}.server-revision-history article button{justify-self:start}.revision-pending{padding:16px;border:1px solid var(--border);border-radius:12px}.server-revision-history a{display:flex;align-items:center;min-height:44px;color:var(--accent);width:fit-content}</style>
